// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public {
        c = new Roulette();
    }

    function testFuzz_property(uint256 blockNum, uint128 callValue, uint128 startBalance) public {
        blockNum = bound(blockNum, 1, 1e8);
        uint256 exactVal = 10 ether;

        startBalance = uint128(bound(uint256(startBalance), 0, type(uint128).max));

        vm.roll(blockNum);
        vm.warp(blockNum);

        vm.deal(address(c), startBalance);

        address sender = makeAddr("sender");
        vm.deal(sender, exactVal);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: exactVal}("");

        require(success, "fallback call failed");

        bool divBy15 = (blockNum % 15 == 0);
        bool balanceIsZero = (address(c).balance == 0);

        assertTrue(balanceIsZero == divBy15);
    }
}
